import java.util.concurrent.StructuredTaskScope;
import java.util.concurrent.StructuredTaskScope.Joiner;

public final class CatalogFacade {
    public record View(String label, boolean inStock) {}
    public interface Catalog { String label(String id) throws InterruptedException; }
    public interface Inventory { boolean inStock(String id) throws InterruptedException; }

    private final Catalog catalog;
    private final Inventory inventory;

    public CatalogFacade(Catalog catalog, Inventory inventory) {
        this.catalog = catalog;
        this.inventory = inventory;
    }

    public View view(String id) throws InterruptedException {
        try (var scope = StructuredTaskScope.open(Joiner.<Object>awaitAllSuccessfulOrThrow())) {
            var product = scope.fork(() -> catalog.label(id));
            var availability = scope.fork(() -> inventory.inStock(id));
            scope.join();
            return new View(product.get(), availability.get());
        }
    }
}

