        var consumer = new SelectedConsumer();
        var normal = new CatalogFacade(id -> "pencil", id -> true);
        if (!consumer.render(normal, "p-10").equals("pencil:true")) {
            throw new AssertionError("Normal product changed");
        }
        var missing = new CatalogFacade(id -> { throw new ProductMissing(id); }, id -> false);
        if (!consumer.render(missing, "p-99").equals("missing")) {
            throw new AssertionError("Missing-product presentation changed");
        }
        System.out.println("normal and missing product preserved");
    }
}

