import java.util.concurrent.StructuredTaskScope;

public final class SelectedConsumer {
    public String render(CatalogFacade facade, String id) throws InterruptedException {
        try {
            var view = facade.view(id);
            return view.label() + ":" + view.inStock();
        } catch (StructuredTaskScope.FailedException failure) {
            if (failure.getCause() instanceof ProductMissing) return "missing";
            throw failure;
        }
    }
}
